#include <iostream>
#include <vector>
class MyClass {
public:
  std::vector<int> data;
  MyClass(std::vector<int> d) : data(std::move(d)) {}
  MyClass(MyClass&& other) noexcept : data(std::move(other.data)) { std::cout << "Move constructor called\n";}
  MyClass& operator=(MyClass&& other) noexcept {
    if (this != &other) {
      data = std::move(other.data);
      std::cout << "Move assignment operator called\n";
    }
    return *this;
  }
  MyClass(const MyClass& other) : data(other.data) { std::cout << "Copy constructor called\n";}
  MyClass& operator=(const MyClass& other) {
    if (this != &other) {
      data = other.data;
      std::cout << "Copy assignment operator called\n";
    }
    return *this;
  }
  ~MyClass() { std::cout << "Destructor called\n";}
};
int main() {
  std::vector<int> vec = {1, 2, 3, 4, 5};
  MyClass obj1(vec);
  MyClass obj2 = std::move(obj1);
  MyClass obj3 = obj2; 
  return 0;
}
